import React from "react";
import { render, screen, fireEvent } from "@testing-library/react";
import { axe } from "jest-axe";
import FileUpload from ".";
import {
  mockMultipleFile,
  mockSingleFile,
  mockSingleFileError,
  mockSingleFileRetry,
  mockSingleFileSize,
  mockSingleFileType,
} from "./mockData";

// test util
const renderFileUpload = (props: any, rerender?: any) => {
  const { onAdd = () => {}, onDelete = () => {}, ...rest } = props;
  const defaultProps = { onAdd, onDelete, "data-testid": "root-id", ...rest };
  const wrapper = rerender
    ? rerender(<FileUpload {...defaultProps} />)
    : render(<FileUpload {...defaultProps} />);

  const fileInput = screen.getByLabelText(/Browse File/, {
    selector: "input",
  }) as HTMLInputElement;
  const dropzone = screen.getByTestId("root-id");
  return {
    ...wrapper,
    dropzone,
    fileInput,
    expectFileDelete: (count: number) => {
      expect(screen.queryAllByRole("button", { name: /Delete/ })).toHaveLength(
        count
      );
    },
    expectFileRetry: (count: number) => {
      expect(screen.queryAllByRole("button", { name: /Retry/ })).toHaveLength(
        count
      );
    },
    getFileDeleteButton: (index: number) => {
      return screen.queryAllByRole("button", { name: /Delete/ })[index];
    },
    getFileRetryButton: (index: number) => {
      return screen.queryAllByRole("button", { name: /Retry/ })[index];
    },
    getOverlay: () => {
      // eslint-disable-next-line
      return wrapper.container.querySelector(".ds-fileupload-overlay");
    },
  };
};

describe("File Upload component", () => {
  it("browse pass A11Y", async () => {
    const { container } = renderFileUpload({ files: mockSingleFile });
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("DND pass A11Y", async () => {
    const { container } = renderFileUpload({
      dragAndDrop: true,
      files: mockSingleFile,
    });
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("browse upload", async () => {
    const onAdd = jest.fn();
    const onDelete = jest.fn();
    const { fileInput, getFileDeleteButton, rerender } = renderFileUpload({
      onAdd,
      onDelete,
    });

    // upload a file
    const file = new File(["Example"], "Example.png", { type: "image/png" });
    fireEvent.change(fileInput, { target: { files: [file] } });
    expect(fileInput.files[0]).toBe(file);
    expect(onAdd).toHaveBeenCalledTimes(1);
    const files = onAdd.mock.calls[0][0];
    expect(files).toHaveLength(1);
    expect(files[0].data.name).toEqual("Example.png");

    // rerender with uploaded file
    renderFileUpload({ onAdd, onDelete, files }, rerender);
    await screen.findByText("Example.png");

    // delete file
    fireEvent.click(getFileDeleteButton(0));
    expect(onDelete).toHaveBeenCalledTimes(1);

    // rerender with no files
    renderFileUpload({ onAdd, onDelete }, rerender);
    // FIXME failing because files property cannot be simply updated programmatically
    // expect(fileInput.files).toHaveLength(0);
    expect(screen.queryByText("Example.png")).not.toBeInTheDocument();
  });

  it("file error", () => {
    renderFileUpload({ files: mockSingleFileError });
    expect(screen.getByText(/Single file error/)).toBeInTheDocument();
  });

  it("file error with retry", () => {
    const onAdd = jest.fn();
    const onRetry = jest.fn();
    const { getFileRetryButton } = renderFileUpload({
      files: mockSingleFileRetry,
      onAdd,
      onRetry,
    });
    const retryButton = getFileRetryButton(0);
    expect(retryButton).toBeInTheDocument();
    fireEvent.click(retryButton);
    expect(onRetry).toHaveBeenCalledTimes(1);
    expect(onRetry).toHaveBeenLastCalledWith(mockSingleFileRetry[0].id);
  });

  it("file size limit", () => {
    renderFileUpload({ files: mockSingleFileSize, size: 150 });
    expect(screen.getByText(/File size exceeds 150 KB/)).toBeInTheDocument();
  });

  it("file type restriction", () => {
    renderFileUpload({ files: mockSingleFileType, accept: ".png" });
    expect(screen.getByText(/pdf is not allowed/)).toBeInTheDocument();
  });

  it("multiple file", () => {
    const onDelete = jest.fn();
    const onRetry = jest.fn();
    const { expectFileDelete, expectFileRetry, getFileDeleteButton } =
      renderFileUpload({
        files: mockMultipleFile,
        multiple: true,
        onDelete,
        onRetry,
      });
    expectFileDelete(4);
    expectFileRetry(1);
    expect(screen.getAllByText(/File size exceeds 150 KB/)).toHaveLength(1);
    expect(screen.getAllByText(/Uploaded/)).toHaveLength(1);

    fireEvent.click(getFileDeleteButton(2));
    expect(onDelete).toHaveBeenCalledTimes(1);
    expect(onDelete).toHaveBeenLastCalledWith(mockMultipleFile[2].id);
  });

  it("DND upload", async () => {
    const onAdd = jest.fn();
    const { dropzone, rerender } = renderFileUpload({
      dragAndDrop: true,
      onAdd,
    });

    // drop a file
    const file = new File(["Example"], "Example.png", { type: "image/png" });
    fireEvent.drop(dropzone, { dataTransfer: { files: [file] } });
    expect(onAdd).toHaveBeenCalledTimes(1);
    const files = onAdd.mock.calls[0][0];
    expect(files).toHaveLength(1);
    expect(files[0].data.name).toEqual("Example.png");

    // rerender with uploaded file
    renderFileUpload({ dragAndDrop: true, onAdd, files }, rerender);
    await screen.findByText("Example.png");
  });

  it("DND drag over", () => {
    const { dropzone, getOverlay } = renderFileUpload({ dragAndDrop: true });

    fireEvent.dragOver(dropzone);
    expect(getOverlay()).toBeInTheDocument();
    fireEvent.dragLeave(dropzone);
    expect(getOverlay()).not.toBeInTheDocument();
  });

  it("uses custom placeholder messages", () => {
    renderFileUpload({
      dragAndDrop: true,
      message: "Drag files here",
      dragOverMessage: "Release to upload",
    });

    expect(screen.getByText("Drag files here")).toBeInTheDocument();
    const dropzone = screen.getByTestId("root-id");
    fireEvent.dragOver(dropzone);
    expect(screen.getAllByText("Release to upload")).toHaveLength(2);
  });

  it("associates supported files text with input and dropzone", () => {
    const { dropzone, fileInput } = renderFileUpload({
      dragAndDrop: true,
      accept: "image/*",
      size: 100,
    });
    const describedBy = dropzone.getAttribute("aria-describedby");
    expect(describedBy).toBeTruthy();

    expect(fileInput.getAttribute("aria-describedby")).toEqual(describedBy);
    expect(document.getElementById(describedBy || "")).toBeTruthy();
  });

  it("opens file picker with keyboard on browse label", () => {
    const { fileInput } = renderFileUpload({ dragAndDrop: true });
    const browseLabel = screen.getByText("Browse File").closest("label");
    expect(browseLabel).toBeInTheDocument();
    const clickSpy = jest.spyOn(fileInput, "click");
    fireEvent.keyDown(browseLabel as Element, { key: "Enter" });
    expect(clickSpy).toHaveBeenCalledTimes(1);
    fireEvent.keyDown(browseLabel as Element, { key: " " });
    expect(clickSpy).toHaveBeenCalledTimes(2);
  });
});
